frame_eqs_eel:
kick = max(bass - bass_att, 0);
pulse = max(pulse * 0.86, min(kick * 0.9, 1));
q3 = pulse;
phase = phase + 0.01 + 0.02 * min(mid_att, 2);
q1 = phase;

comp:
uniform sampler2D sampler_fw_cover;
 shader_body {

  vec2 s = texsize.xy / min(texsize.x, texsize.y);

  vec2 p = (uv - 0.5) * s;
  float n = 11.0;
  float y = p.y * 0.72 + 0.5;
  float row = floor(y * n);
  float frac = fract(y * n);
  float seed = fract(sin(row * 12.9898) * 43758.5453);
  float dir = (seed < 0.5) ? -1.0 : 1.0;
  float slide = dir * (0.02 + 0.12 * q3 * (0.4 + seed)) + 0.04 * sin(q1 + row * 0.9);
  vec2 c = vec2(p.x * 0.72 + 0.5 + slide, y);

  vec2 cov_m = 1.0 - abs(1.0 - mod(c, 2.0));
  vec3 cov = texture(sampler_fw_cover, vec2(cov_m.x, 1.0 - cov_m.y)).xyz;

  float cl = dot(cov, vec3(0.299, 0.587, 0.114));
  vec2 cg = c + vec2(0.012 + 0.02 * q3, 0.0);

  vec2 ghost_m = 1.0 - abs(1.0 - mod(cg, 2.0));
  vec3 ghost = texture(sampler_fw_cover, vec2(ghost_m.x, 1.0 - ghost_m.y)).xyz;

  float lum = clamp((cl - 0.5) * 1.6 + 0.5, 0.0, 1.0);

  float col_r_x = clamp(lum, 0.0, 1.0) * 5.0;
  vec3 col_r = mix(NOKKVI_RAMP0, NOKKVI_RAMP1, clamp(col_r_x, 0.0, 1.0));
  col_r = mix(col_r, NOKKVI_RAMP2, clamp(col_r_x - 1.0, 0.0, 1.0));
  col_r = mix(col_r, NOKKVI_RAMP3, clamp(col_r_x - 2.0, 0.0, 1.0));
  col_r = mix(col_r, NOKKVI_RAMP4, clamp(col_r_x - 3.0, 0.0, 1.0));
  col_r = mix(col_r, NOKKVI_RAMP5, clamp(col_r_x - 4.0, 0.0, 1.0));

  vec3 col = mix(NOKKVI_BG, col_r, smoothstep(0.02, 0.35, lum));
  col = mix(col, NOKKVI_TEXT, smoothstep(0.85, 1.0, lum) * 0.7);

  col += NOKKVI_WARM * clamp(dot(ghost, vec3(0.299, 0.587, 0.114)) - cl, 0.0, 1.0) * (0.15 + 0.6 * q3);
  float seam = smoothstep(0.06, 0.0, min(frac, 1.0 - frac));
  col = mix(col, NOKKVI_BG, seam * 0.8);
  col += NOKKVI_ACCENT * seam * (0.15 + 0.8 * q3);
  ret = col;
 }
